1932	  const updateAgentPermissions: Handler = async (ctx) => {
1933	    const id = ctx.param("id")!;
1934	    const existing = await svc.getById(id);
1935	    if (!existing) return Response.json({ error: "Agent not found" }, { status: 404 });
1936	    assertCompanyAccess(ctx, existing.companyId);
1937	
1938	    if (ctx.actor?.type === "agent") {
1939	      const actorAgent = ctx.actor.agentId ? await svc.getById(ctx.actor.agentId) : null;
1940	      if (!actorAgent || actorAgent.companyId !== existing.companyId) {
1941	        return Response.json({ error: "Forbidden" }, { status: 403 });
1942	      }
1943	      if (actorAgent.role !== "ceo") {
1944	        return Response.json({ error: "Only CEO can manage permissions" }, { status: 403 });
1945	      }
1946	    } else {
1947	      await assertBoardCanManageAgentsForCompany(ctx, existing.companyId);
1948	    }
1949	
1950	    const body = await ctx.json<Record<string, unknown>>();
1951	    const agent = await svc.updatePermissions(id, body);
1952	    if (!agent) return Response.json({ error: "Agent not found" }, { status: 404 });
1953	
1954	    const effectiveCanAssignTasks =
1955	      agent.role === "ceo" || Boolean(agent.permissions?.canCreateAgents) || body.canAssignTasks;
1956	    await access.ensureMembership(agent.companyId, "agent", agent.id, "member", "active");
1957	    await access.setPrincipalPermission(
1958	      agent.companyId,
1959	      "agent",
1960	      agent.id,
1961	      "tasks:assign",
1962	      Boolean(effectiveCanAssignTasks),
1963	      ctx.actor?.type === "board" ? (ctx.actor.userId ?? null) : null,
1964	    );
1965	
1966	    const actor = getActorInfo(ctx);
1967	    await logActivity(db, {
1968	      companyId: agent.companyId,
1969	      actorType: actor.actorType,
1970	      actorId: actor.actorId,
1971	      agentId: actor.agentId,
1972	      runId: actor.runId,
1973	      action: "agent.permissions_updated",
1974	      entityType: "agent",
1975	      entityId: agent.id,
1976	      details: {
1977	        canCreateAgents: agent.permissions?.canCreateAgents ?? false,
1978	        canAssignTasks: Boolean(effectiveCanAssignTasks),
1979	      },
1980	    });
1981	
1982	    return Response.json(await buildAgentDetail(agent));
1983	  };
